<?php require_once __DIR__.'/../includes/auth.php';$pageTitle='Sales';$base='/shop-inventory-management';$q=trim($_GET['q']??'');$sql='SELECT s.*,u.full_name,(SELECT COUNT(*) FROM sale_items si WHERE si.sale_id=s.id) item_count FROM sales s LEFT JOIN users u ON u.id=s.user_id';$args=[];if($q!==''){$sql.=' WHERE s.invoice_no LIKE ?';$args[]='%'.$q.'%';}$sql.=' ORDER BY s.id DESC LIMIT 200';$st=$pdo->prepare($sql);$st->execute($args);$rows=$st->fetchAll();require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/sidebar.php';?>
<div class="page-heading"><div><h1>Sales</h1><p>Review invoices and record cash sales.</p></div><a class="btn primary" href="create.php">＋ New sale</a></div><div class="panel"><form class="toolbar" method="get"><input name="q" placeholder="Search invoice number…" value="<?=e($q)?>"><button class="btn">Search</button><a class="btn" href="index.php">Reset</a></form><div class="table-wrap"><table><thead><tr><th>Invoice</th><th>Date</th><th>Items</th><th>Recorded by</th><th>Total</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="7" class="empty">No sales recorded.</td></tr><?php else:foreach($rows as $r):?><tr><td><strong><?=e($r['invoice_no'])?></strong></td><td><?=e($r['created_at'])?></td><td><?=$r['item_count']?></td><td><?=e($r['full_name']??'Admin')?></td><td><?=money($r['grand_total'])?></td><td><span class="badge success"><?=e(ucfirst($r['status']))?></span></td><td class="actions"><a class="btn small" href="view.php?id=<?=$r['id']?>">View</a><a class="btn small" href="invoice.php?id=<?=$r['id']?>" target="_blank">Invoice / Print</a></td></tr><?php endforeach;endif;?></tbody></table></div></div><?php require __DIR__.'/../includes/footer.php';?>
